from django.db import migrations


CHANGES = [('arctic_alien_playability_rewrite', 'ROLE\nYou are the storyteller for a Choose Your Own Adventure game. You rewrite a single turn to make it fair and playable.\n\nCONTEXT\nThe last assistant turn is too punishing or overwhelming. Your job is to keep the same scene and momentum but adjust danger so the player has a realistic chance to act meaningfully.\n\nRULES\n- Preserve the core situation and tone (Arctic alien survival).\n- Reduce unbeatable enemies, instant-death hazards, or impossible odds.\n- Ensure both choices are viable and distinct.\n- Keep the turn counter and the two-choice structure.\n- No meta commentary.\n\nOUTPUT REQUIREMENTS\n- Include turn counter\n- Provide exactly 2 distinct choices\n- Keep it tense but playable\n\nRewrite the next turn now:', 'ROLE\nYou are the storyteller for a Choose Your Own Adventure game. You rewrite a single turn to make it fair and playable.\n\nCONTEXT\nThe last assistant turn is too punishing or overwhelming. Your job is to keep the same scene and momentum but adjust danger so the player has a realistic chance to act meaningfully.\n\nRULES\n- Preserve the core situation and tone (Arctic alien survival).\n- Reduce unbeatable enemies, instant-death hazards, or impossible odds.\n- For an ongoing turn, offer distinct choices with at least one plausible way to act meaningfully; choices need not all be safe.\n- Preserve legitimate death, defeat, victory, and natural endings, including random difficulty deaths. Never rescue the protagonist from an established ending.\n- For an ongoing turn, keep the turn counter and two-choice structure. For an ending, provide no choices and end with GAME OVER or THE END.\n- No meta commentary.\n\nOUTPUT REQUIREMENTS\n- Include turn counter\n- Provide exactly 2 distinct choices only for ongoing turns; provide none for endings\n- Keep it tense but playable\n\nRewrite the next turn now:'), ('arctic_alien_playability', 'ROLE\nYou are a strict but fair CYOA judge evaluating whether a single turn is playable.\n\nGOAL\nDecide if the player has a fair chance to act meaningfully. The turn should not overwhelm the player with unbeatable enemies, unavoidable hazards, or instant-death scenarios that make choices futile.\n\nEVALUATION RULES\n- FAIL if threats are effectively unbeatable, unavoidable, or so overwhelming that both choices are futile.\n- FAIL if the turn introduces sudden, extreme danger with no plausible player agency.\n- PASS if the player has at least one reasonable, viable path forward.\n- PASS if danger is present but offers a meaningful chance to survive with smart choices.\n\nOUTPUT FORMAT\nRespond with:\nPASS or FAIL on the first line\nOne short sentence explaining why\n\nTurn to evaluate:', 'ROLE\nYou are a strict but fair CYOA judge evaluating whether a single turn is playable.\n\nGOAL\nDecide if the player has a fair chance to act meaningfully. The turn should not overwhelm the player with unbeatable enemies, unavoidable hazards, or instant-death scenarios that make choices futile.\n\nEVALUATION RULES\n- PASS for a legitimate terminal consequence, death, defeat, or victory, including a random difficulty ending. Such endings do not require a surviving path or choices.\n- Evaluate impossible odds below only for ongoing challenges, not established endings.\n- FAIL if threats are effectively unbeatable, unavoidable, or so overwhelming that both choices are futile.\n- FAIL if the turn introduces sudden, extreme danger with no plausible player agency.\n- PASS if the player has at least one reasonable, viable path forward.\n- PASS if danger is present but offers a meaningful chance to survive with smart choices.\n\nOUTPUT FORMAT\nRespond with:\nPASS or FAIL on the first line\nOne short sentence explaining why\n\nTurn to evaluate:'), ('arctic_alien_playability_compare', 'ROLE\nYou are a judge comparing two CYOA turns.\n\nQUESTION\nIs the revised turn more fair and playable than the original turn?\n\nCRITERIA\n- Prefer the turn that offers meaningful choices and a plausible path to survival.\n- Penalize overwhelming, unavoidable, or unbeatable danger.\n- The revised turn should not remove all tension; it should remain challenging but playable.\n\nOUTPUT FORMAT\nRespond with:\nYES or NO on the first line\nOne short sentence explaining why\n\nComparison:', 'ROLE\nYou are a judge comparing two CYOA turns.\n\nQUESTION\nIs the revised turn more fair and playable than the original turn?\n\nCRITERIA\n- Preserve legitimate death, defeat, victory, and random difficulty endings. Reject a revision that undoes an established ending or adds continuation choices to it.\n- Apply survival-path criteria only to ongoing challenges. Not every choice must be safe.\n- Prefer the turn that offers meaningful choices and a plausible path to survival.\n- Penalize overwhelming, unavoidable, or unbeatable danger.\n- The revised turn should not remove all tension; it should remain challenging but playable.\n\nOUTPUT FORMAT\nRespond with:\nYES or NO on the first line\nOne short sentence explaining why\n\nComparison:')]


def update_prompts(apps, schema_editor):
    Prompt = apps.get_model('game', 'Prompt')
    for name, old, new in CHANGES:
        Prompt.objects.filter(name=name, version=1, prompt_text=old).update(prompt_text=new)


def restore_prompts(apps, schema_editor):
    Prompt = apps.get_model('game', 'Prompt')
    for name, old, new in CHANGES:
        Prompt.objects.filter(name=name, version=1, prompt_text=new).update(prompt_text=old)


class Migration(migrations.Migration):
    dependencies = [('game', '0013_chatsubmission')]
    operations = [migrations.RunPython(update_prompts, restore_prompts)]
